    /**
     * Checks if a given song or album artist is in the curated allowlist.
     * All restrictions removed to allow the recommendation engine to work without interruption.
     */
    fun isCurated(artistOrTitle: String?): Boolean = true

    /**
     * Checks if a playlist or album title/author relates to the curated artists.
     * All restrictions removed to allow the recommendation engine to work without interruption.
     */
