    /**
     * Maps Audiometa returned genre tags for an artist into the respective Curated Energy Category.
     */
    fun mapGenreToEnergyCategory(genres: List<String>): EnergyCategory? {
        for (genre in genres) {
            val g = genre.lowercase().trim()
            when {
                g.contains("hip hop") || g.contains("rap") || g.contains("trap") || g.contains("banger") || g.contains("drill") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("High Energy") }
                g.contains("ambient") || g.contains("lo-fi") || g.contains("chill") || g.contains("acoustic") || g.contains("focus") || g.contains("downtempo") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Deep Focus") }
                g.contains("r&b") || g.contains("soul") || g.contains("neo-soul") || g.contains("melanchol") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Late Night") }
                g.contains("pop") || g.contains("dance") || g.contains("synth") || g.contains("electropop") || g.contains("teen pop") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Global Pop") }
                g.contains("filmi") || g.contains("bollywood") || g.contains("desi") || g.contains("indian") || g.contains("punjabi") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Desi") }
                g.contains("rock") || g.contains("metal") || g.contains("grunge") || g.contains("alternative") || g.contains("classic rock") || g.contains("punk") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Rock") }
                g.contains("reggaeton") || g.contains("latin") || g.contains("urbano") || g.contains("trap latino") || g.contains("salsa") || g.contains("bachata") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Latin Heat") }
                g.contains("workout") || g.contains("gym") || g.contains("power") || g.contains("electro house") || g.contains("hardstyle") ->
                    return ENERGY_CATEGORIES.firstOrNull { it.name.startsWith("Workout Power") }
            }
        }
        return null
    }
}
